-- PostgreSQL migration blueprint. Firebase remains the deployed backend adapter.
-- UUIDs are generated by the application; timestamps use UTC.
-- Apply membership/owner row-level policies before exposing any of these tables.
CREATE TABLE users (id uuid PRIMARY KEY, auth_subject text UNIQUE NOT NULL, display_name text NOT NULL, privacy jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE riders (id uuid PRIMARY KEY REFERENCES users(id), vehicle text, photo_url text, preferred_language text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE emergency_contacts (id uuid PRIMARY KEY, rider_id uuid NOT NULL REFERENCES riders(id), name text NOT NULL, relationship text, encrypted_phone bytea, encrypted_medical_info bytea, consented_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rides (id uuid PRIMARY KEY, leader_id uuid NOT NULL REFERENCES riders(id), name text NOT NULL, join_code_hash text UNIQUE NOT NULL, status text NOT NULL CHECK(status IN ('upcoming','active','paused','completed')), visibility text NOT NULL DEFAULT 'Private', capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 50), starts_at timestamptz, ended_at timestamptz, simulated boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ride_members (ride_id uuid REFERENCES rides(id), rider_id uuid REFERENCES riders(id), role text NOT NULL CHECK(role IN ('leader','sweep','rider')), status text NOT NULL, briefing_accepted_at timestamptz, check_in jsonb, live_location jsonb, location_expires_at timestamptz, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(ride_id,rider_id));
CREATE UNIQUE INDEX one_sweep ON ride_members(ride_id) WHERE role='sweep';
CREATE TABLE routes (id uuid PRIMARY KEY, ride_id uuid UNIQUE NOT NULL REFERENCES rides(id), private_geometry jsonb, distance_meters numeric, estimated_minutes integer, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE waypoints (id uuid PRIMARY KEY, route_id uuid NOT NULL REFERENCES routes(id), sequence integer NOT NULL, kind text NOT NULL, name text NOT NULL, latitude numeric CHECK(latitude BETWEEN -90 AND 90), longitude numeric CHECK(longitude BETWEEN -180 AND 180), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(route_id,sequence));
CREATE TABLE hazards (id uuid PRIMARY KEY, ride_id uuid NOT NULL REFERENCES rides(id), reporter_id uuid NOT NULL REFERENCES riders(id), type text NOT NULL, severity text NOT NULL, description text NOT NULL, latitude numeric NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude numeric NOT NULL CHECK(longitude BETWEEN -180 AND 180), direction text, photo_object_id text, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz);
CREATE TABLE hazard_confirmations (hazard_id uuid REFERENCES hazards(id), rider_id uuid REFERENCES riders(id), present boolean NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(hazard_id,rider_id));
CREATE TABLE incidents (id uuid PRIMARY KEY, ride_id uuid NOT NULL REFERENCES rides(id), rider_id uuid REFERENCES riders(id), sensor_source text, telemetry jsonb, simulated boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sos_events (id uuid PRIMARY KEY, ride_id uuid NOT NULL REFERENCES rides(id), rider_id uuid NOT NULL REFERENCES riders(id), incident_id uuid REFERENCES incidents(id), category text NOT NULL, status text NOT NULL CHECK(status IN ('Reported','Acknowledged','Help on the way','Resolved','Cancelled')), private_location jsonb, confirmed_at timestamptz NOT NULL, resolved_at timestamptz);
CREATE TABLE ride_events (id uuid PRIMARY KEY, ride_id uuid NOT NULL REFERENCES rides(id), rider_id uuid REFERENCES riders(id), type text NOT NULL, severity text NOT NULL CHECK(severity IN ('INFO','WARNING','CRITICAL')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ride_timeline ON ride_events(ride_id,created_at);
CREATE TABLE notifications (id uuid PRIMARY KEY, event_id uuid REFERENCES ride_events(id), recipient_id uuid NOT NULL REFERENCES users(id), channel text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, read_at timestamptz);
CREATE TABLE ride_statistics (ride_id uuid PRIMARY KEY REFERENCES rides(id), distance_meters numeric, duration_seconds integer, avg_speed_kph numeric, max_speed_kph numeric, stops_completed integer, source text NOT NULL, calculated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE direct_messages (id uuid PRIMARY KEY, ride_id uuid NOT NULL REFERENCES rides(id), sender_id uuid NOT NULL REFERENCES users(id), recipient_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
-- Public projections intentionally omit routes, joining secrets and rider identity.
CREATE VIEW public_rides AS SELECT id,name,starts_at,capacity,status FROM rides WHERE visibility='Public' AND status<>'completed';
